/** static void FillFactoryFrontierTrainerParty(u16 trainerId, u8 firstMonId) */
export function FillFactoryFrontierTrainerParty(...args: any[]): any {
  let i, j;
      let friendship: any = null;
      let level: any = null;
      let fixedIV: any = null;
      let otID: any = null;

      if (trainerId < FRONTIER_TRAINERS_COUNT)
      {
          let lvlMode = gSaveBlock2Ptr.frontier.lvlMode;
          let battleMode = VarGet(VAR_FRONTIER_BATTLE_MODE);
          let challengeNum = gSaveBlock2Ptr.frontier.factoryWinStreaks[battleMode][lvlMode] / FRONTIER_STAGES_PER_CHALLENGE;
          let lvlMode = gSaveBlock2Ptr.frontier.lvlMode;
          let battleMode = VarGet(VAR_FRONTIER_BATTLE_MODE);
          let challengeNum = gSaveBlock2Ptr.frontier.towerWinStreaks[battleMode][FRONTIER_LVL_50] / FRONTIER_STAGES_PER_CHALLENGE;
          if (gSaveBlock2Ptr.frontier.curChallengeBattleNum < FRONTIER_STAGES_PER_CHALLENGE - 1)
              fixedIV = GetFactoryMonFixedIV(challengeNum, FALSE);
          else
              fixedIV = GetFactoryMonFixedIV(challengeNum, TRUE);  
      }
      else if (trainerId == TRAINER_EREADER)
      {
          for (i = firstMonId; i < firstMonId + FRONTIER_PARTY_SIZE; i++)
              CreateBattleTowerMon(gEnemyParty[i], gSaveBlock2Ptr.frontier.ereaderTrainer.party[i - firstMonId]);
          return;
      }
      else if (trainerId == TRAINER_FRONTIER_BRAIN)
      {
          FillFactoryBrainParty();
          return;
      }
      else
      {
          fixedIV = MAX_PER_STAT_IVS;
      }

      level = SetFacilityPtrsGetLevel();
      otID = T1_READ_32(gSaveBlock2Ptr.playerTrainerId);
      for (i = 0; i < FRONTIER_PARTY_SIZE; i++)
      {
          let monId = gFrontierTempParty[i];
          CreateMonWithEVSpreadNatureOTID(gEnemyParty[firstMonId + i],
                                               gFacilityTrainerMons[monId].species,
                                               level,
                                               gFacilityTrainerMons[monId].nature,
                                               fixedIV,
                                               gFacilityTrainerMons[monId].evSpread,
                                               otID);

          friendship = 0;
          for (j = 0; j < MAX_MON_MOVES; j++)
              SetMonMoveAvoidReturn(gEnemyParty[firstMonId + i], gFacilityTrainerMons[monId].moves[j], j);

          SetMonData(gEnemyParty[firstMonId + i], MON_DATA_FRIENDSHIP, friendship);
          SetMonData(gEnemyParty[firstMonId + i], MON_DATA_HELD_ITEM, gBattleFrontierHeldItems[gFacilityTrainerMons[monId].itemTableId]);
      }
}

